 if(classroomId&&data.studentNames!=null||!classroomId&&!Array.isArray(data.studentNames))return invalid();let names:string[];
 if(classroomId){const target=targets.classrooms.find(c=>c.id===classroomId);if(!target)throw new QuizError('quiz.practiceTarget',403);names=target.students;}
 else{if((data.studentNames as unknown[]).some(n=>typeof n!=='string'))return invalid();names=[...new Set(data.studentNames as string[])];if(names.some(n=>!targets.students.some(s=>s.studentName===n)))throw new QuizError('quiz.practiceTarget',403);}
 if(!names.length||names.length>200)throw new QuizError('quiz.practiceTarget');if(data.immediate!==undefined&&typeof data.immediate!=='boolean'||policy.kind==='quiz'&&data.immediate===true)return invalid('quiz.invalidAssignmentSettings');
 const now=new Date().toISOString(),db=learningDb(),v=source.v.id;if(policy.dueAt&&policy.dueAt<=now)throw new QuizError('quiz.invalidSchedule');
 const sourceGuard=`EXISTS(SELECT 1 FROM quiz_versions sv JOIN quizzes sq ON sq.id=sv.quiz_id JOIN tuition_groups sg ON sg.id=sq.group_id AND sg.active=1 WHERE sv.id=? AND sq.deleted_at IS NULL AND ((sq.group_id=? AND (sq.owner_id=? OR ?='admin') AND sv.revision=sq.revision) OR (sv.revision=sq.shared_revision AND (sq.visibility='public' OR sq.visibility='organisation' AND sq.group_id=?))))`;
 const input={groupId:'?',subject:"''",...(a.role==='teacher'?{teacherName:'?'}:{}),allowCrossSubject:'1'},inputValues=[g,...(a.role==='teacher'?[a.teacherName]:[])];
